:root {
  /* ========== 色彩基盤 ========== */
  /* 県庁の落ち着いたトーン：深い紺と薄い灰白を基調に、
     公共機関の信頼感と厳粛性を表現。
     暗めの背景に白文字で、長時間の監査業務に対応。 */

  --primary: #2c3e50;
  --primary-hover: #1a252f;
  --bg-main: #0f1419;
  --bg-card: #1a1f28;
  --bg-sidebar: #151a22;
  --border: #2a3142;
  --text: #e8eaed;
  --text-muted: #9ca3af;
  --top-bar-bg: #1f2937;
  --top-bar-border: #374151;
  --top-bar-text: #f3f4f6;

  /* ========== タイポグラフィ ========== */
  /* 県庁システムの格式を保ちながら、
     セキュリティ監査の緊張感を和らげる可読性重視の書体選定 */
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Hiragino Sans", "Hiragino Kaku Gothic ProN", "Yu Gothic", "Meiryo", sans-serif;

  /* ========== 角丸・影 ========== */
  /* 公共機関の堅牢性と現代的な親しみやすさの折衷。
     カード類は控えめな角丸で、影は淡く奥行きを表現。 */
  --radius-card: 6px;
  --radius-control: 4px;
  --shadow-card: 0 2px 8px rgba(0, 0, 0, 0.4);

  /* ========== 境界・寸法 ========== */
  /* セキュリティシステムの視認性を確保しつつ、
     過度な装飾を避ける。境界線は控えめで、
     要素間の距離で階層を表現。 */
  --border-width: 1px;
  --control-height: 36px;
  --space-unit: 8px;

  /* ========== アニメーション ========== */
  /* 監査ログの大量データ処理時の応答性を示しながら、
     落ち着きを損なわない速度。 */
  --motion-duration: 200ms;

  /* ========== 質感・テクスチャ ========== */
  /* 県庁の公式文書のような紙質感と、
     デジタルシステムの清潔感を融合。
     微細な織目パターンで深みを表現。 */
  --surface-texture: repeating-linear-gradient(
    90deg,
    transparent,
    transparent 2px,
    rgba(255, 255, 255, 0.02) 2px,
    rgba(255, 255, 255, 0.02) 4px
  ),
  repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(255, 255, 255, 0.015) 2px,
    rgba(255, 255, 255, 0.015) 4px
  );
  --surface-texture-size: 100% 100%;
  --surface-texture-position: 0 0;
}
