function(container, apiUrl, tables) {
  const paymentMethodRadios = container.querySelectorAll('input[name="payment-method"]');
  const creditCardFields = container.querySelector('#credit-card-fields');
  const bankTransferFields = container.querySelector('#bank-transfer-fields');
  const convenienceStoreFields = container.querySelector('#convenience-store-fields');
  const executePaymentBtn = container.querySelector('#execute-payment-btn');
  const paymentStatus = container.querySelector('#payment-status');
  const paymentResult = container.querySelector('#payment-result');
  const downloadSection = container.querySelector('#download-section');
  const backButton = container.querySelector('[data-testid="back-button"]');
  const copyBankInfoBtn = container.querySelector('[data-testid="copy-bank-info"]');

  let selectedPaymentMethod = null;
  let reservationData = null;

  // Initialize: Load reservation data from session/localStorage
  async function initializeReservation() {
    // In a real scenario, this would come from a previous screen or API
    // For now, we'll use mock data or retrieve from tables
    const reservationId = sessionStorage.getItem('reservationId');

    if (reservationId && tables.length > 0) {
      // Try to find reservation in tables
      const reservations = tables.find(t => t.tableName === '予約');
      if (reservations && reservations.records) {
        reservationData = reservations.records.find(r => r.id === reservationId);
      }
    }

    // Fallback to mock data for demo
    if (!reservationData) {
      reservationData = {
        id: 'res-001',
        facilityName: '〇〇体育館',
        reservationDate: '2025-02-15',
        startTime: '10:00',
        endTime: '12:00',
        people: 20,
        unitPrice: 5000,
        durationHours: 2,
        totalAmount: 10000
      };
    }

    displayReservationSummary();
  }

  function displayReservationSummary() {
    if (!reservationData) return;

    container.querySelector('[data-testid="facility-name"]').textContent = reservationData.facilityName || '—';
    container.querySelector('[data-testid="reservation-date"]').textContent = reservationData.reservationDate || '—';
    container.querySelector('[data-testid="reservation-time"]').textContent = 
      `${reservationData.startTime || '—'} ～ ${reservationData.endTime || '—'}`;
    container.querySelector('[data-testid="reservation-people"]').textContent = 
      `${reservationData.people || 0} 名`;
    container.querySelector('[data-testid="unit-price"]').textContent = 
      `¥${(reservationData.unitPrice || 0).toLocaleString()}`;
    container.querySelector('[data-testid="duration-hours"]').textContent = 
      `${reservationData.durationHours || 0} 時間`;
    container.querySelector('[data-testid="subtotal"]').textContent = 
      `¥${((reservationData.unitPrice || 0) * (reservationData.durationHours || 0)).toLocaleString()}`;
    container.querySelector('[data-testid="total-amount"]').textContent = 
      `¥${(reservationData.totalAmount || 0).toLocaleString()}`;
  }

  // Payment method selection
  paymentMethodRadios.forEach(radio => {
    radio.addEventListener('change', (e) => {
      selectedPaymentMethod = e.target.value;
      updatePaymentFields();
      updateExecuteButtonState();
    });
  });

  function updatePaymentFields() {
    creditCardFields.style.display = selectedPaymentMethod === 'credit_card' ? 'block' : 'none';
    bankTransferFields.style.display = selectedPaymentMethod === 'bank_transfer' ? 'block' : 'none';
    convenienceStoreFields.style.display = selectedPaymentMethod === 'convenience_store' ? 'block' : 'none';
  }

  function updateExecuteButtonState() {
    if (selectedPaymentMethod) {
      executePaymentBtn.disabled = false;
      executePaymentBtn.style.opacity = '1';
      executePaymentBtn.style.cursor = 'pointer';
    } else {
      executePaymentBtn.disabled = true;
      executePaymentBtn.style.opacity = '0.5';
      executePaymentBtn.style.cursor = 'not-allowed';
    }
  }

  // Copy bank info to clipboard
  if (copyBankInfoBtn) {
    copyBankInfoBtn.addEventListener('click', () => {
      const bankInfo = '銀行名：〇〇銀行\n支店名：〇〇支店\n口座種別：普通\n口座番号：1234567';
      navigator.clipboard.writeText(bankInfo).then(() => {
        const originalText = copyBankInfoBtn.textContent;
        copyBankInfoBtn.textContent = 'コピーしました';
        setTimeout(() => {
          copyBankInfoBtn.textContent = originalText;
        }, 2000);
      });
    });
  }

  // Execute payment
  executePaymentBtn.addEventListener('click', async () => {
    if (!selectedPaymentMethod || !reservationData) return;

    // Disable button and show processing
    executePaymentBtn.disabled = true;
    paymentStatus.style.display = 'block';
    paymentResult.style.display = 'none';
    downloadSection.style.display = 'none';

    try {
      // Simulate payment processing
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Create payment record
      const paymentData = {
        reservationId: reservationData.id,
        paymentMethod: selectedPaymentMethod,
        amount: reservationData.totalAmount,
        status: 'completed',
        transactionId: 'TXN-' + Date.now(),
        timestamp: new Date().toISOString()
      };

      // Save payment via API if available
      if (window.aivicApi) {
        const paymentTableIndex = tables.findIndex(t => t.tableName === '決済');
        if (paymentTableIndex >= 0) {
          await window.aivicApi.save(paymentTableIndex, paymentData);
        }
      }

      // Show success message
      paymentStatus.style.display = 'none';
      showPaymentSuccess(paymentData);
      downloadSection.style.display = 'block';

      // Auto-redirect after 5 seconds
      setTimeout(() => {
        // In real scenario: window.location.href = '/completion';
        console.log('Redirecting to completion page...');
      }, 5000);

    } catch (error) {
      paymentStatus.style.display = 'none';
      showPaymentError(error.message);
    } finally {
      executePaymentBtn.disabled = false;
    }
  });

  function showPaymentSuccess(paymentData) {
    const resultContent = container.querySelector('#result-content');
    resultContent.innerHTML = `
      <div style="display: flex; align-items: center; gap: 12px; margin-bottom: 12px;">
        <div style="width: 24px; height: 24px; background: var(--primary); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-weight: 700;">✓</div>
        <div>
          <div style="font-weight: 600; color: var(--text); font-size: 14px;">決済が完了しました</div>
          <div style="font-size: 12px; color: var(--text-muted); margin-top: 2px;">予約が確定いたしました。確認メールをお送りしています。</div>
        </div>
      </div>
      <div style="padding: 12px; background: rgba(255,255,255,0.02); border-radius: 4px; border: 1px solid var(--border); margin-top: 12px; font-size: 12px;">
        <div style="margin-bottom: 6px;"><span style="color: var(--text-muted);">トランザクションID：</span><span style="color: var(--text); font-weight: 500; font-family: monospace;">${paymentData.transactionId}</span></div>
        <div style="margin-bottom: 6px;"><span style="color: var(--text-muted);">決済金額：</span><span style="color: var(--text); font-weight: 500;">¥${paymentData.amount.toLocaleString()}</span></div>
        <div><span style="color: var(--text-muted);">決済方法：</span><span style="color: var(--text); font-weight: 500;">${getPaymentMethodLabel(paymentData.paymentMethod)}</span></div>
      </div>
    `;
    paymentResult.style.display = 'block';
  }

  function showPaymentError(errorMessage) {
    const resultContent = container.querySelector('#result-content');
    resultContent.innerHTML = `
      <div style="display: flex; align-items: center; gap: 12px;">
        <div style="width: 24px; height: 24px; background: #d32f2f; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-weight: 700;">!</div>
        <div>
          <div style="font-weight: 600; color: #d32f2f; font-size: 14px;">決済に失敗しました</div>
          <div style="font-size: 12px; color: var(--text-muted); margin-top: 2px;">${errorMessage || '決済処理中にエラーが発生しました。もう一度お試しください。'}</div>
        </div>
      </div>
    `;
    paymentResult.style.display = 'block';
    paymentResult.style.borderColor = '#d32f2f';
    paymentResult.style.background = 'rgba(211, 47, 47, 0.1)';
  }

  function getPaymentMethodLabel(method) {
    const labels = {
      'credit_card': 'クレジットカード',
      'bank_transfer': '銀行振込',
      'convenience_store': 'コンビニ決済'
    };
    return labels[method] || method;
  }

  // Back button
  backButton.addEventListener('click', () => {
    // In real scenario: window.history.back() or navigate to facility selection
    console.log('Navigating back...');
  });

  // Download buttons
  const downloadReceiptBtn = container.querySelector('[data-testid="download-receipt"]');
  const downloadConfirmationBtn = container.querySelector('[data-testid="download-confirmation"]');

  if (downloadReceiptBtn) {
    downloadReceiptBtn.addEventListener('click', () => {
      // Simulate PDF download
      const link = document.createElement('a');
      link.href = 'data:text/plain;charset=utf-8,' + encodeURIComponent('領収書\n\n施設名：' + reservationData.facilityName);
      link.download = 'receipt.pdf';
      link.click();
    });
  }

  if (downloadConfirmationBtn) {
    downloadConfirmationBtn.addEventListener('click', () => {
      // Simulate PDF download
      const link = document.createElement('a');
      link.href = 'data:text/plain;charset=utf-8,' + encodeURIComponent('予約確認書\n\n施設名：' + reservationData.facilityName);
      link.download = 'confirmation.pdf';
      link.click();
    });
  }

  // Initialize
  initializeReservation();
}
